function setPdfPreview(on){if(on&&entities.length)buildPrintReport();document.body.classList.toggle('pdf-preview-mode',on);$('exitPdfPreview').hidden=!on;$('trialConversion').hidden=on||stage!==6;document.querySelectorAll('[data-stage-panel]').forEach((p)=>{const active=Number(p.dataset.stagePanel)===stage;p.hidden=!active;p.classList.toggle('active',active);});window.scrollTo({top:on?0:Math.max(0,document.querySelector(`[data-stage-panel="${stage}"]`).offsetTop-150),behavior:'smooth'});}
